from pathlib import Path
import json,csv,html,re,shutil,hashlib,os
from datetime import datetime,timezone
from PIL import Image,ImageDraw,ImageFont
R=Path(__file__).resolve().parents[2];O=R/'artifacts/report-interpretation-20260924';D=R/'artifacts/bunya/nine-class-baselines-20260923/final-20260924';A=D/'analysis'
def load(p):return json.loads(Path(p).read_text())
def rows(p):return list(csv.DictReader(Path(p).open(encoding='utf-8-sig')))
def E(x):return html.escape(str(x),quote=True)
def bi(z,e):return '<span data-l="zh">'+E(z)+'</span><span data-l="en" hidden>'+E(e)+'</span>'
def p(z,e,cls=''):return '<p class="'+cls+'">'+bi(z,e)+'</p>'
def h(z,e,n=2):return '<h'+str(n)+'>'+bi(z,e)+'</h'+str(n)+'>'
def link(url,z,e=None):return '<a href="'+E(url)+'">'+bi(z,e or z)+'</a>'
def fig(url,z,e):return '<figure><a href="'+url+'" target="_blank"><img loading="lazy" src="'+url+'" alt="'+E(e)+'"></a><figcaption>'+bi(z,e)+'</figcaption></figure>'
def table(headers,rr):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+bi(*x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rr)+'</tbody></table></div>'
def copytree(src,dst):
 dst.mkdir(parents=True,exist_ok=True)
 for q in src.rglob('*'):
  if q.is_file():
   target=dst/q.relative_to(src);target.parent.mkdir(parents=True,exist_ok=True)
   if target.exists():target.unlink()
   if q.suffix=='.png':os.link(q,target)
   else:shutil.copy2(q,target)
def block(identity,parts):
 return '<section class="interpretation" id="'+identity+'">'+h('读图与讨论','Analysis and discussion',3)+''.join(p(z,e) for z,e in parts)+'</section>'
def firstrow(f,m,d):return next(r for r in f['first'] if r['method']==m and r['direction']==d)
def pct(x):return f'{float(x)*100:.1f}%'
def class_discussion(f):
 n=f['class_name'];hu=firstrow(f,'HU-MCD','C-Insertion');mc=firstrow(f,'MCD','C-Insertion');ac=firstrow(f,'ACE','C-Insertion');de=firstrow(f,'HU-MCD','C-Deletion');base=de['full_image_accuracy_same_cohort'];aa=next(r for r in f['baselines'] if r['method']=='ACE');narr=[]
 narr.append((f"观察：HU-MCD 首次删除后准确率从同一贡献集的 {pct(base)} 降至 {pct(de['first_change_accuracy'])}，平均删除 {float(de['changed_pixels_percent']):.1f}% 像素（n={de['contributors']}）；首次插入为 {pct(hu['first_change_accuracy'])}。这是实际计算点，不是补齐或插值结果。",f"Observation: HU-MCD's first deletion reduces accuracy from {pct(base)} on the same contributing cohort to {pct(de['first_change_accuracy'])}, deleting {float(de['changed_pixels_percent']):.1f}% of pixels on average (n={de['contributors']}); first insertion reaches {pct(hu['first_change_accuracy'])}. These are actual computed points, not padded or interpolated values."))
 narr.append((f"方法差异：首次插入的 HU-MCD／MCD／ACE 准确率为 {pct(hu['first_change_accuracy'])}／{pct(mc['first_change_accuracy'])}／{pct(ac['first_change_accuracy'])}，但平均可见像素分别为 {float(hu['changed_pixels_percent']):.1f}%／{float(mc['changed_pixels_percent']):.1f}%／{float(ac['changed_pixels_percent']):.1f}%，贡献数分别为 {hu['contributors']}／{mc['contributors']}／{ac['contributors']}。必须联合阅读，不能将相同步数当作相同信息量。",f"Method contrast: first-insertion accuracy is {pct(hu['first_change_accuracy'])}/{pct(mc['first_change_accuracy'])}/{pct(ac['first_change_accuracy'])} for HU-MCD/MCD/ACE, but mean visible fractions are {float(hu['changed_pixels_percent']):.1f}%/{float(mc['changed_pixels_percent']):.1f}%/{float(ac['changed_pixels_percent']):.1f}%, with n={hu['contributors']}/{mc['contributors']}/{ac['contributors']}. Equal step numbers do not mean equal exposed information."))
 special={
 'airliner':('本类 HU-MCD 的早期插入优势很明显，但 MCD 的初始聚类与最终分配差异也较大。应把下面的成员转换和实际图片结合起来，而不是把它直接归因为飞机部件更易解释。','HU-MCD has a clear early-insertion advantage here, while MCD shows substantial initial-to-final membership change. Read the transition evidence and actual images together; this does not establish that aircraft parts are more understandable.'),
 'golden_retriever':('Golden 是历史诊断最完整的类别，不是独立于十类评价的另一实验。ACE 的三个保留概念全部低于控制均值；其首步只有49张贡献，不能把低插入率解释为ACE方法的一般结论。','Golden is the most extensively diagnosed historical class, not a separate experiment outside the ten-class evaluation. All three ACE retained candidates score below control; only49 images contribute at its first step. Low insertion accuracy is not a general conclusion about ACE.'),
 'hummingbird':('MCD 首次插入准确率高于 HU-MCD，但同时显示约38%而不是13%的像素，暴露量接近三倍。ACE 的10个保留概念均低于随机控制；需要把参考筛选行为与视觉质量分开。','MCD has higher first-insertion accuracy but exposes about38% rather than13% of pixels, nearly three times as much. All10 retained ACE candidates score below control. Separate reference filtering behavior from visual quality.'),
 'Siamese_cat':('HU-MCD 首次插入较强，但也比 MCD 和 ACE 显示更多像素。MCD 只有三个概念，粗粒度划分可能影响每一步的区域大小；这是一种待验证解释，不是本结果已隔离的因果因素。','HU-MCD has stronger first insertion but also exposes more pixels than MCD or ACE. MCD has only three concepts; coarse partitioning may affect step size. This is a hypothesis, not an isolated causal effect.'),
 'tailed_frog':('三方法首步恢复均有限。ACE 的36%准确率高于 HU-MCD/MCD 的24%，但它暴露约42%像素而两者约22%/21%。不能用这一个点声称 ACE 更忠实；也应关注原型中的背景／手部等上下文是否真实参与预测。','All methods recover limited accuracy at the first step. ACE reaches36% versus24% for HU-MCD/MCD, but exposes about42% of pixels versus22%/21%. This point does not establish greater faithfulness. Context such as background or hands merits separate inspection for actual predictive influence.'),
 'container_ship':('HU-MCD 和 ACE 首步可见像素接近21%，准确率分别64%和32%；这是可描述的局部差异，但不是匹配了每张图片区域后的受控比较。MCD 首步只有约11%可见像素，尤其不能直接按首步率排序。','HU-MCD and ACE expose about21% on average at the first step, with64% versus32% accuracy. This is a descriptive local contrast, not a comparison with per-image regions matched. MCD exposes only about11%, so step-one ranking is particularly misleading.'),
 'police_van':('本类不存在 HU-MCD 在所有原生步骤都优于基线的模式：首次插入为62%，MCD64%、ACE70%，ACE同时显示更多像素。全体汇总趋势不能代替类别级讨论。','HU-MCD is not uniformly better at every native step here: first insertion is62%, versus64% for MCD and70% for ACE, which also exposes more pixels. The pooled trend cannot replace class-level discussion.'),
 'beach_wagon':('ACE 的首步56%高于 HU-MCD52%，但其平均可见区域约32%，相比HU-MCD18%明显更大。概念数量不能用作语义质量证据。','ACE reaches56% versus52% for HU-MCD at the first step, while exposing about32% versus18% of pixels. Concept count is not evidence of semantic quality.'),
 'zebra':('三方法早期恢复总体较高；HU-MCD92%与ACE94%仅差一张图片，且掩码不同。这不是显著性检验，也不应包装为确定的优劣结论。','Early recovery is high. HU-MCD92% versus ACE94% differs by one image, with different masks. This is not a significance test or a decisive superiority result.'),
 'ox':('HU-MCD、MCD、ACE首步准确率均较低，且MCD略高并不代表整个曲线占优。ACE保留11个概念，其中9个低于控制；应优先检查候选筛选方向和实际区域，而不是增加概念数来改善结果。','All three methods have low first-step accuracy; a slightly higher MCD value does not establish dominance over the whole curve. Nine of11 retained ACE candidates score below control. Inspect filtering direction and actual regions rather than increasing concept count to improve the result.')}
 # Fixed prose uses only accepted numeric facts; no image-level causal attribution.
 z,e=special[n];narr.append((z,e))
 narr.append((f"解释边界：ACE名义保留 {aa['retained_concepts']} 个，均值高于／低于控制为 {aa['nominal_retained_above_control']}／{aa['nominal_retained_below_control']}。后续曲线贡献人数变化；空概念、零特征、排序及输入处理规则均保留。当前结果支持对已执行协议的描述，不证明概念可理解，也不能直接确定差异的单一原因。",f"Limits: ACE retains {aa['retained_concepts']} under its nominal gate; {aa['nominal_retained_above_control']}/{aa['nominal_retained_below_control']} have means above/below control. Later contributors vary; absent concepts, zero features, ordering and input rules are retained. Results describe the executed protocol, not human understandability or a single established cause."))
 return narr

def apply(stage):
 S=Path(stage)
 for src in load(O/'sources.json'):
  if str(A) in src['path']:assert hashlib.sha256(Path(src['path']).read_bytes()).hexdigest()==src['sha256'], 'Accepted data changed: rerun interpretation prepare.py'
 facts=load(O/'facts.json');cards=load(O/'comparison-cards.json');summary=load(O/'summary.json');out=S/'hub/interpretation';out.mkdir(parents=True,exist_ok=True)
 for name in ['facts.json','comparison-cards.json','summary.json','sources.json','golden-reused-examples.json','paper-page7.png','paper-page8.png','supplement-page1.png','qualitative-observations.json']:
  shutil.copy2(O/name,out/name)
 for name in ['panels','golden-unified']:copytree(O/name,out/name)
 template=(S/'baseline-progress.html').read_text()
 def page(name,title,body):
  main='<main id="main"><div class="eyebrow">'+bi('论文覆盖与解释更新 · 2026-09-24','Paper coverage and interpretation · 24 Sep2026')+'</div>'+h(*title,1)+body+'</main>'
  text=re.sub(r'<main\b[^>]*>.*?</main>',lambda _:main,template,flags=re.S);text=re.sub(r'<title>.*?</title>','<title>'+E(title[0])+' | HU-MCD</title>',text);(S/name).write_text(text)
 interpretations=[]
 def remember(name,parts):interpretations.append(dict(id=name,paragraphs=[dict(zh=z,en=e) for z,e in parts]));return block(name,parts)
 countparts=[('观察：十类HU-MCD共147个学习概念；初始cluster数有5/10类与论文表值一致，其余相差1。completeness与论文已舍入数值的最大绝对差约0.02255，Zebra偏低、Ox偏高。','Observation: HU-MCD yields147 learned concepts. Initial cluster counts match the published counts in5/10 classes; other differences are one cluster. The largest absolute completeness difference from rounded paper values is about0.02255, lower for Zebra and higher for Ox.'),('解释：这支持发现规模和权重空间覆盖大体接近，不等于精确复现。论文只给两位小数，并未分别报告过滤前后数量；我们的固定清单、灰度规则和随机性也不同。不能根据这些差异断言实现错了，或反过来声称论文数值已逐项重现。','Interpretation: discovery scale and weight-space coverage are broadly close, not exactly replicated. The paper gives two-decimal values and does not separate pre/post-filter counts. Frozen images, grayscale handling and randomness differ. These differences alone establish neither an implementation error nor exact numeric reproduction.'),('进一步关注：cluster数由分割统计与公开代码规则决定，completeness度量分类权重在概念并集的覆盖；二者都不衡量成员是否语义一致。需要与随机成员、背景内容及人工审阅同时读。','Attention: counts follow segmentation statistics and released rules; completeness measures classifier-weight coverage by the concept union. Neither measures semantic member consistency. Read them alongside random members, background content and human review.')]
 curveparts=[('观察：四方法全图准确率均为82.4%。首个实际概念步骤中，HU-MCD平均删除23.66%像素后准确率36.0%，插入同区域为62.6%；MCD对应23.00%／56.6%／49.0%，ACE为22.88%／60.32%／39.28%，ACE此时n=499，其余n=500。','Observation: all four methods start at82.4% full-image accuracy. At the first actual concept step HU-MCD deletes23.66% of pixels on average and reaches36.0% accuracy, or62.6% upon insertion. MCD gives23.00%/56.6%/49.0%; ACE22.88%/60.32%/39.28%, with n=499 for ACE and500 otherwise.'),('趋势：在这组固定输入与参考协议下，HU-MCD早期较强地改变预测，汇总方向与论文Fig.4相符；但类别内存在反例和交叉，不能写成每类、每个像素预算都优于基线。平均面积接近也不等于逐图区域匹配。','Trend: under these frozen inputs and reference protocols, HU-MCD changes predictions more strongly early, directionally consistent with Fig.4. Class-level exceptions and crossings remain; this is not superiority in every class or pixel budget. Similar mean areas do not imply per-image matched regions.'),('与原文的距离：Fig.4可以比较曲线形态，不能当作同输入的数值复验。作者逐图清单和原始曲线点未在当前证据中建立；我们的ACE早期插入相对Random的形态也并非原图完全重现。禁止从图上猜精确作者数值或用缺失端点计算新AUC。','Distance from the paper: Fig.4 supports a shape-level comparison, not same-input numeric replication. Author per-image manifests and raw curve points are not established in our evidence; our early ACE insertion relative to Random also does not exactly reproduce the published shape. Do not infer precise author values from pixels or manufacture endpoints/AUC.'),('边界：横轴是实际平均像素比例，点按原生步骤聚合；保留n>375，后续样本及类别权重会变化。Random每步约1%像素，概念每步面积不同。局部预测影响、全局重要性和人类理解是三个不同问题。','Limits: x is actual mean pixel fraction; points aggregate native steps with n>375, so later samples and class weights change. Random steps expose about1%, while concept steps differ. Local predictive influence, global importance and human understanding are distinct questions.')]
 directionparts=[('观察：MCD保留47个学习概念，HU-MCD147个，ACE138个名义保留候选。MCD按k=3…19首次completeness>.5停止；HU按分割统计决定cluster数，ACE从25候选筛选，发现图片分别为400/400/50。ACE其中113个均值高于控制、25个低于；Golden3/3、Hummingbird10/10低于，Ox为9/11。','Observation: MCD retains47 learned concepts, HU-MCD147 and ACE138 nominally retained candidates. MCD stops at the first completeness>.5 over k=3…19; HU derives cluster count from segmentation statistics and ACE filters25 candidates, with discovery budgets400/400/50. Of the ACE candidates113 have means above control and25 below; Golden3/3, Hummingbird10/10 and Ox9/11 are below.'),('解释：方法发现图片数、表示和停止／筛选规则不同，不能把概念越多理解为越好；MCD较低completeness也受既定停止条件影响，不能单独当作表示能力较差的证据。ACE原双侧检验检测差异方向不限，因此保留低于控制的候选与源码规则一致；它不是“优于控制”的单侧证据，重复负样本还限制p值的统计解释。','Interpretation: discovery budgets, representations and stopping/filtering rules differ; more concepts is not better by definition. MCD’s lower completeness also reflects its prescribed stopping condition, not isolated evidence of inferior representation capacity. ACE’s two-sided gate admits either direction, so retaining below-control candidates follows the code. It is not one-sided evidence of superiority, and repeated negatives further limit p-value interpretation.'),('需要后续判断：先区分参考代码复现与修正统计协议。若评估方向筛选或独立负样本对结果的影响，须另行冻结对比协议；本报告没有静默修正筛选，也没有重新拟合。','Next decision: separate released-code reproduction from corrected statistical protocols. Testing directional filtering or independent negatives requires a separately frozen comparison protocol. No filtering correction or refit is applied here.')]
