 # Update chart-adjacent interpretation in existing pages, preserving all existing details and forms.
 def add_after_chart(text,path,identity,parts):
  text=re.sub(r'<section class="interpretation" id="'+re.escape(identity)+r'">.*?</section>','',text,flags=re.S)
  pattern=r'(<figure>.*?<img[^>]*src="'+re.escape(path)+r'".*?</figure>)'
  match=re.search(pattern,text,re.S)
  if match:return text[:match.end()]+remember(identity,parts)+text[match.end():]
  return text
